/**
 * Real Geographic Landmass Polygons & Topology
 * Sourced from Natural Earth (countries-50m, Public Domain).
 * Generated by scripts/build-geography.ts.
 *
 * Whole country polygons retained without artificial straight clipping edges.
 */

export interface LandPolygon {
    bbox: [number, number, number, number]; // [minLng, minLat, maxLng, maxLat]
    rings: [number, number][][];           // outer ring at [0], inner holes at [1...]
}

export interface CountryLand {
    name: string;
    bbox: [number, number, number, number]; // [minLng, minLat, maxLng, maxLat]
    labelPoint: [number, number];          // [lng, lat] inside polygon
    polygons: LandPolygon[];
}

export interface CoverageRegion {
    name: string;
    minLng: number;
    maxLng: number;
    minLat: number;
    maxLat: number;
}

