/**
 * Checks whether a given geographic bounding envelope is fully covered
 * by the pre-loaded land dataset regions.
 */
export function isEnvelopeCovered(
    minLng: number,
    maxLng: number,
    minLat: number,
    maxLat: number
): boolean {
    return LAND_COVERAGE_REGIONS.some((region) => {
        return (
            minLng >= region.minLng &&
            maxLng <= region.maxLng &&
            minLat >= region.minLat &&
            maxLat <= region.maxLat
        );
    });
}

/**
 * Standard ray-casting point-in-polygon test.
 */
export function pointInPolygonRing(pt: [number, number], ring: [number, number][]): boolean {
    const [x, y] = pt;
    let inside = false;
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
        const [xi, yi] = ring[i];
        const [xj, yj] = ring[j];
        const intersect = ((yi > y) !== (yj > y)) && (x < ((xj - xi) * (y - yi)) / (yj - yi) + xi);
        if (intersect) inside = !inside;
    }
    return inside;
}

/**
 * Tests whether a point lies within any of the country's polygons (accounting for holes).
 */
export function pointInCountry(pt: [number, number], country: CountryLand): boolean {
    const [x, y] = pt;
    const [minX, minY, maxX, maxY] = country.bbox;
    if (x < minX || x > maxX || y < minY || y > maxY) return false;

    for (const poly of country.polygons) {
        const [pMinX, pMinY, pMaxX, pMaxY] = poly.bbox;
        if (x < pMinX || x > pMaxX || y < pMinY || y > pMaxY) continue;

        // Must be inside outer ring
        if (!pointInPolygonRing(pt, poly.rings[0])) continue;

        // Must not be inside any hole
        let inHole = false;
        for (let k = 1; k < poly.rings.length; k++) {
            if (pointInPolygonRing(pt, poly.rings[k])) {
                inHole = true;
                break;
            }
        }
        if (!inHole) return true;
    }
    return false;
}

/**
 * Identifies the country of a given stop coordinate with coastal tolerance.
 */
export function getCountryForPoint(lng: number, lat: number, dataset = COUNTRIES_LAND): string | null {
    // 1. Direct point-in-polygon test
    for (const country of dataset) {
        if (pointInCountry([lng, lat], country)) {
            return country.name;
        }
    }

    // 2. Tolerance test for coastal/island stops in 50m resolution (~0.05 deg ~ 5km)
    const offsets = [
        [0.02, 0], [-0.02, 0], [0, 0.02], [0, -0.02],
        [0.04, 0], [-0.04, 0], [0, 0.04], [0, -0.04],
        [0.06, 0.02], [-0.06, -0.02], [0.02, 0.06], [-0.02, -0.06],
    ];
    for (const country of dataset) {
        for (const [dx, dy] of offsets) {
            if (pointInCountry([lng + dx, lat + dy], country)) {
                return country.name;
            }
        }
    }

    return null;
}

/**
 * Returns ordered, deduplicated country badges for a journey's stops.
 */
export function getCountryBadgesForStops(
    stops: { lng: number; lat: number }[],
    dataset = COUNTRIES_LAND
): string[] {
    const badges: string[] = [];
    const seen = new Set<string>();

    for (const stop of stops) {
        const country = getCountryForPoint(stop.lng, stop.lat, dataset);
        if (country && !seen.has(country)) {
            seen.add(country);
            badges.push(country);
        }
    }

    return badges;
}
